/* CatatRapi front-end. Local previews use demo storage; Netlify deployments use the same-origin /api proxy to Apps Script + Google Sheets. */
const DB_KEY = 'catatrapi_demo_database_v1';
const SESSION_KEY = 'catatrapi_session_v1';
const fmt = new Intl.NumberFormat('id-ID', {style:'currency', currency:'IDR', maximumFractionDigits:0});
const monthFmt = new Intl.DateTimeFormat('id-ID', {month:'short'});
const fullDateFmt = new Intl.DateTimeFormat('id-ID', {day:'2-digit',month:'short',year:'numeric'});
const $ = (q, parent=document) => parent.querySelector(q);
const $$ = (q, parent=document) => [...parent.querySelectorAll(q)];
const uid = (prefix='id') => `${prefix}_${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;
const isoDate = (d=new Date()) => new Date(d).toISOString().slice(0,10);
const currentMonth = () => isoDate().slice(0,7);
const rupiah = value => fmt.format(Number(value || 0));
const cleanNum = value => Math.round(Number(value || 0));

const DEFAULT_ACCOUNTS = [
  ['1100','Kas','asset'],['1110','Bank','asset'],['1120','Piutang Usaha','asset'],['1130','Persediaan','asset'],['1210','Peralatan','asset'],
  ['2100','Utang Usaha','liability'],['2200','Utang Bank','liability'],['3100','Modal Pemilik','equity'],['3200','Saldo Laba','equity'],
  ['4100','Pendapatan Usaha','income'],['4200','Pendapatan Lainnya','income'],['5100','Harga Pokok Penjualan','expense'],['6100','Beban Sewa','expense'],['6200','Beban Utilitas','expense'],['6300','Beban Gaji','expense'],['6400','Beban Transportasi','expense'],['6500','Beban Lainnya','expense'],['6600','Beban Pajak','expense']
];

const state = { db:null, user:null, token:null, activeBookId:null, currentView:'dashboard', report:'income', accountFilter:'all', remote:false };
const driveStorage = () => window.CatatRapiDriveStorage || null;
const requiresDriveActions = new Set(['createBook','createAccount','createJournal','voidJournal','correctJournal','createBudget','shareBook']);

function toast(message, kind='') { const el=document.createElement('div'); el.className=`toast ${kind}`; el.textContent=message; $('#toast-region').append(el); setTimeout(()=>el.remove(), 3800); }
function escapeHTML(v='') { return String(v).replace(/[&<>'"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function initials(name='') { return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase() || 'A'; }
function normalSide(type) { return ['asset','expense'].includes(type) ? 'Debit' : 'Kredit'; }
function typeLabel(type) { return ({asset:'Aset',liability:'Kewajiban',equity:'Ekuitas',income:'Pendapatan',expense:'Beban'})[type] || type; }
function roleLabel(role) { return ({owner:'Pemilik',editor:'Editor',viewer:'Pembaca'})[role] || role; }
function dateKey(value){const text=String(value||''),match=text.match(/^\d{4}-\d{2}-\d{2}/);if(match)return match[0];const parsed=new Date(text);return Number.isNaN(parsed.getTime())?'':parsed.toISOString().slice(0,10);}
function journalDate(value){const key=dateKey(value);return key?new Date(`${key}T00:00:00`):new Date(NaN);}
function sameMonth(date, month=currentMonth()) { return dateKey(date).slice(0,7) === month; }

async function hashPin(pin, salt) {
  const data = new TextEncoder().encode(pin); const saltData = new TextEncoder().encode(salt);
  if (window.crypto && crypto.subtle) { const key = await crypto.subtle.importKey('raw', data, 'PBKDF2', false, ['deriveBits']); const bits = await crypto.subtle.deriveBits({name:'PBKDF2', salt:saltData, iterations:120000, hash:'SHA-256'}, key, 256); return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join(''); }
  // Only a fallback for an old browser in demo mode, never use this as production authentication.
  let value = `${pin}|${salt}`; for(let i=0;i<12000;i++) value = btoa(unescape(encodeURIComponent(value))).slice(0,120); return value;
}
function randomSalt() { const bytes=new Uint8Array(16); crypto.getRandomValues(bytes); return [...bytes].map(x=>x.toString(16).padStart(2,'0')).join(''); }
function loadLocalDb() { try { return JSON.parse(localStorage.getItem(DB_KEY)) || {users:[],books:[],members:[],accounts:[],journals:[],journalLines:[],budgets:[],audit:[]}; } catch { return {users:[],books:[],members:[],accounts:[],journals:[],journalLines:[],budgets:[],audit:[]}; } }
function saveLocalDb() { localStorage.setItem(DB_KEY, JSON.stringify(state.db)); }
function isLocalPreview() { const host=window.location.hostname; return host==='localhost'||host==='127.0.0.1'||host.endsWith('.e2b.app'); }
function getApiUrl() { return isLocalPreview() ? '' : '/api'; }
function isDriveMode() { return Boolean(driveStorage()?.isActive()); }
function connectionLabel() {
  if (isDriveMode()) return '● Google Drive pribadi aktif';
  if (!getApiUrl()) return '● Mode demo';
  return '● Google Drive belum terhubung';
}

async function api(action, data={}) {
  const drive=driveStorage();
  if (drive?.handles(action)) return drive.handle(action, data, {state, localApi, dbKey:DB_KEY});
  if (requiresDriveActions.has(action) && getApiUrl()) throw new Error('Hubungkan Google Drive pribadi terlebih dahulu. CatatRapi tidak menyimpan transaksi ke spreadsheet pusat.');
  const url=getApiUrl();
  if (!url) return localApi(action, data);
  let response;
  try { response=await fetch(url, {method:'POST', headers:{'Content-Type':'text/plain;charset=utf-8'}, body:JSON.stringify({action, token:state.token, ...data})}); }
  catch { throw new Error('Tidak dapat menghubungi server CatatRapi. Periksa koneksi atau konfigurasi Netlify.'); }
  let result;
  try { result=await response.json(); }
  catch { throw new Error('Server mengirim respons tidak valid. Periksa Netlify Function dan URL Apps Script.'); }
  if (!response.ok || !result.ok) throw new Error(result.error || 'Permintaan ke server gagal.');
  return result.data;
}
async function localApi(action, data={}) {
  state.db = state.db || loadLocalDb();
  const db=state.db;
  const findUser = username => db.users.find(u=>u.username.toLowerCase()===String(username).toLowerCase());
  if (action==='health') return {mode:'local'};
  if (action==='register') {
    const username=String(data.username).trim().toLowerCase();
    if (!/^[a-z0-9._-]{3,32}$/.test(username)) throw new Error('Nama pengguna hanya boleh huruf kecil, angka, titik, garis bawah, atau tanda minus.');
    if (!/^\d{6,16}$/.test(data.pin)) throw new Error('PIN harus terdiri dari 6–16 angka.');
    if (findUser(username)) throw new Error('Nama pengguna ini sudah digunakan.');
    const salt=randomSalt(); const verifier=await hashPin(data.pin,salt); const user={id:uid('usr'),name:String(data.name).trim(),username,salt,verifier,createdAt:new Date().toISOString(),active:true};
    db.users.push(user); const book=createLocalBook(user.id, `${user.name.split(' ')[0]} — Pribadi`, 'personal', new Date().getFullYear()); db.audit.push({id:uid('aud'),at:new Date().toISOString(),userId:user.id,action:'REGISTER',detail:'Akun dan buku awal dibuat'}); saveLocalDb(); return {user:{id:user.id,name:user.name,username:user.username}, book};
  }
  if (action==='login') { const user=findUser(data.username); if (!user || !user.active || await hashPin(data.pin,user.salt)!==user.verifier) throw new Error('Nama pengguna atau PIN tidak sesuai.'); const token=uid('session'); sessionStorage.setItem(SESSION_KEY,JSON.stringify({token,userId:user.id,username:user.username})); return {token,user:{id:user.id,name:user.name,username:user.username}}; }
  const session=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null'); const user=db.users.find(u=>u.id===session?.userId); if (!user) throw new Error('Sesi berakhir. Silakan masuk kembali.');
  if (action==='bootstrap') { const accessible=accessibleBookIds(user.id); return {user:{id:user.id,name:user.name,username:user.username},books:db.books.filter(b=>accessible.includes(b.id)),members:db.members.filter(m=>accessible.includes(m.bookId)),accounts:db.accounts.filter(a=>accessible.includes(a.bookId)),journals:db.journals.filter(j=>accessible.includes(j.bookId)),journalLines:db.journalLines.filter(l=>accessible.includes(l.bookId)),budgets:db.budgets.filter(b=>accessible.includes(b.bookId)),users:db.users.map(u=>({id:u.id,name:u.name,username:u.username}))}; }
  if (action==='createBook') { const book=createLocalBook(user.id,data.name,data.type,data.year); audit(user.id,'CREATE_BOOK',book.id); saveLocalDb(); return {book,accounts:db.accounts.filter(a=>a.bookId===book.id)}; }
  if (action==='createAccount') { mustEdit(data.bookId,user.id); if (db.accounts.some(a=>a.bookId===data.bookId && a.code===data.code)) throw new Error('Kode akun sudah digunakan dalam buku ini.'); const account={id:uid('acc'),bookId:data.bookId,code:String(data.code),name:String(data.name),type:data.type,active:true,createdAt:new Date().toISOString()}; db.accounts.push(account); audit(user.id,'CREATE_ACCOUNT',account.id); saveLocalDb(); return {account}; }
  if (action==='createJournal') { mustEdit(data.bookId,user.id); validateJournal(data.lines, db.accounts.filter(a=>a.bookId===data.bookId)); const journal={id:uid('jrn'),bookId:data.bookId,date:data.date,reference:data.reference||'',description:data.description,status:'posted',createdBy:user.id,createdAt:new Date().toISOString(),reversalOfId:'',correctsJournalId:'',replacedById:'',voidReason:'',voidedAt:''}; db.journals.push(journal); data.lines.forEach(line=>db.journalLines.push({id:uid('lin'),journalId:journal.id,bookId:data.bookId,accountId:line.accountId,debit:cleanNum(line.debit),credit:cleanNum(line.credit),memo:line.memo||''})); audit(user.id,'CREATE_JOURNAL',journal.id); saveLocalDb(); return {journal,lines:db.journalLines.filter(l=>l.journalId===journal.id)}; }
  if (action==='voidJournal') { const original=db.journals.find(j=>j.id===data.journalId&&j.bookId===data.bookId); const result=voidLocalJournal(original,user,data.reason); saveLocalDb(); return result; }
  if (action==='correctJournal') { const original=db.journals.find(j=>j.id===data.journalId&&j.bookId===data.bookId),reason=String(data.reason||'').trim(); if(!original)throw new Error('Transaksi yang akan dikoreksi tidak ditemukan.'); if(reason.length<3)throw new Error('Isi alasan koreksi minimal 3 karakter.'); assertCorrectLocalJournal(original,user); validateJournal(data.lines,db.accounts.filter(a=>a.bookId===data.bookId)); const voided=voidLocalJournal(original,user,'Koreksi: '+reason); const journal={id:uid('jrn'),bookId:data.bookId,date:data.date,reference:data.reference||'',description:data.description,status:'posted',createdBy:user.id,createdAt:new Date().toISOString(),reversalOfId:'',correctsJournalId:original.id,replacedById:'',voidReason:'',voidedAt:''}; db.journals.push(journal); const lines=data.lines.map(line=>{const row={id:uid('lin'),journalId:journal.id,bookId:data.bookId,accountId:line.accountId,debit:cleanNum(line.debit),credit:cleanNum(line.credit),memo:line.memo||''};db.journalLines.push(row);return row;}); original.replacedById=journal.id; audit(user.id,'CORRECT_JOURNAL',`${original.id} -> ${journal.id}: ${reason}`); saveLocalDb(); return {original,reversal:voided.reversal,reversalLines:voided.reversalLines,journal,lines}; }
  if (action==='createBudget') { mustEdit(data.bookId,user.id); const old=db.budgets.find(b=>b.bookId===data.bookId&&b.accountId===data.accountId&&b.month===data.month); if(old){old.amount=cleanNum(data.amount);old.note=data.note||'';} else db.budgets.push({id:uid('bud'),bookId:data.bookId,accountId:data.accountId,month:data.month,amount:cleanNum(data.amount),note:data.note||'',createdAt:new Date().toISOString()}); audit(user.id,'UPSERT_BUDGET',data.bookId); saveLocalDb(); return {budgets:db.budgets.filter(b=>b.bookId===data.bookId)}; }
  if (action==='shareBook') { const book=db.books.find(b=>b.id===data.bookId); if(!book||book.ownerId!==user.id) throw new Error('Hanya pemilik yang dapat mengatur akses.'); const target=findUser(data.username); if(!target) throw new Error('Nama pengguna tujuan belum terdaftar.'); if(target.id===user.id) throw new Error('Anda sudah menjadi pemilik buku ini.'); let member=db.members.find(m=>m.bookId===book.id&&m.userId===target.id); if(member) member.role=data.role; else {member={id:uid('mem'),bookId:book.id,userId:target.id,role:data.role,addedAt:new Date().toISOString()};db.members.push(member);} audit(user.id,'SHARE_BOOK',`${book.id}:${target.id}`); saveLocalDb(); return {member,user:{id:target.id,name:target.name,username:target.username}}; }
  if(action==='logout'){sessionStorage.removeItem(SESSION_KEY);return {}};
  throw new Error('Aksi tidak dikenal.');
}
function accessibleBookIds(userId) { return state.db.books.filter(b=>b.ownerId===userId).map(b=>b.id).concat(state.db.members.filter(m=>m.userId===userId).map(m=>m.bookId)); }
function mustEdit(bookId,userId) { const book=state.db.books.find(b=>b.id===bookId); const role=book?.ownerId===userId?'owner':state.db.members.find(m=>m.bookId===bookId&&m.userId===userId)?.role; if(!['owner','editor'].includes(role)) throw new Error('Anda hanya memiliki akses baca untuk buku ini.'); }
function assertCorrectLocalJournal(journal,user){if(!journal)throw new Error('Transaksi tidak ditemukan.');if(journal.status!=='posted')throw new Error('Transaksi ini sudah dibatalkan atau dikoreksi.');const book=state.db.books.find(b=>b.id===journal.bookId),role=book?.ownerId===user.id?'owner':state.db.members.find(m=>m.bookId===journal.bookId&&m.userId===user.id)?.role;if(role==='owner'||(role==='editor'&&journal.createdBy===user.id))return;throw new Error('Anda hanya dapat mengoreksi transaksi yang Anda buat sendiri.');}
function voidLocalJournal(journal,user,reason){assertCorrectLocalJournal(journal,user);const cleanReason=String(reason||'').trim();if(cleanReason.length<3)throw new Error('Isi alasan pembatalan minimal 3 karakter.');const timestamp=new Date().toISOString(),sourceLines=state.db.journalLines.filter(line=>line.journalId===journal.id),reversal={id:uid('jrn'),bookId:journal.bookId,date:journal.date,reference:`VOID-${journal.reference||journal.id}`.slice(0,40),description:`Pembatalan: ${journal.description}`.slice(0,160),status:'reversal',createdBy:user.id,createdAt:timestamp,reversalOfId:journal.id,correctsJournalId:'',replacedById:'',voidReason:'',voidedAt:''};state.db.journals.push(reversal);const reversalLines=sourceLines.map(line=>{const row={id:uid('lin'),journalId:reversal.id,bookId:journal.bookId,accountId:line.accountId,debit:cleanNum(line.credit),credit:cleanNum(line.debit),memo:`Jurnal pembalik ${journal.id}`};state.db.journalLines.push(row);return row;});journal.status='voided';journal.voidReason=cleanReason;journal.voidedAt=timestamp;audit(user.id,'VOID_JOURNAL',`${journal.id}: ${cleanReason}`);return {journal,reversal,reversalLines};}
function audit(userId,action,detail) { state.db.audit.push({id:uid('aud'),at:new Date().toISOString(),userId,action,detail}); }
function createLocalBook(ownerId,name,type,year) { const book={id:uid('book'),ownerId,name:String(name).trim(),type,year:Number(year),currency:'IDR',createdAt:new Date().toISOString()}; state.db.books.push(book); DEFAULT_ACCOUNTS.forEach(([code,accountName,accountType])=>state.db.accounts.push({id:uid('acc'),bookId:book.id,code,name:accountName,type:accountType,active:true,createdAt:new Date().toISOString()})); return book; }
function validateJournal(lines, accounts) { if(!Array.isArray(lines)||lines.length<2) throw new Error('Jurnal memerlukan minimal dua baris.'); const valid=new Set(accounts.map(a=>a.id)); let debit=0,credit=0; lines.forEach(l=>{if(!valid.has(l.accountId)) throw new Error('Salah satu akun jurnal tidak valid.'); debit+=cleanNum(l.debit);credit+=cleanNum(l.credit);if(cleanNum(l.debit)>0&&cleanNum(l.credit)>0)throw new Error('Satu baris hanya boleh debit atau kredit.');}); if(debit<=0||credit<=0||debit!==credit)throw new Error('Total debit dan kredit harus sama dan lebih dari nol.'); }

function hydrate(data) {
  state.user=data.user; state.db={users:data.users||[],books:data.books||[],members:data.members||[],accounts:data.accounts||[],journals:(data.journals||[]).map(journal=>({...journal,date:dateKey(journal.date)})),journalLines:data.journalLines||[],budgets:data.budgets||[],audit:data.audit||[]};
  const stored=localStorage.getItem('catatrapi_active_book'); const accessible=state.db.books.map(b=>b.id); state.activeBookId=accessible.includes(stored)?stored:(state.db.books[0]?.id||null); if(state.activeBookId)localStorage.setItem('catatrapi_active_book',state.activeBookId);
}
function activeBook() { return state.db.books.find(b=>b.id===state.activeBookId); }
function currentRole(bookId=state.activeBookId) { const book=state.db.books.find(b=>b.id===bookId); if(!book)return 'viewer'; if(book.ownerId===state.user.id)return 'owner'; return state.db.members.find(m=>m.bookId===bookId&&m.userId===state.user.id)?.role||'viewer'; }
function canEdit() { return ['owner','editor'].includes(currentRole()); }
function accounts() { return state.db.accounts.filter(a=>a.bookId===state.activeBookId).sort((a,b)=>String(a.code||'').localeCompare(String(b.code||''),'id',{numeric:true})); }
function journals() { return state.db.journals.filter(j=>j.bookId===state.activeBookId).sort((a,b)=>`${b.date}${b.createdAt}`.localeCompare(`${a.date}${a.createdAt}`)); }
function linesFor(journalId) { return state.db.journalLines.filter(l=>l.journalId===journalId); }
function accountById(id) { return state.db.accounts.find(a=>a.id===id); }
function balanceOf(accountId, cutoff=null) { const account=accountById(accountId); let debits=0,credits=0; state.db.journalLines.filter(l=>l.accountId===accountId).forEach(l=>{const j=state.db.journals.find(x=>x.id===l.journalId);if(j&&(!cutoff||j.date<=cutoff)){debits+=cleanNum(l.debit);credits+=cleanNum(l.credit);}}); return ['asset','expense'].includes(account?.type)?debits-credits:credits-debits; }
function accountBalanceByType(type, cutoff=null) { return accounts().filter(a=>a.type===type).reduce((sum,a)=>sum+balanceOf(a.id,cutoff),0); }
function monthlyActivity(type, month=currentMonth()) { let total=0; journals().filter(j=>sameMonth(j.date,month)).forEach(j=>linesFor(j.id).forEach(l=>{const a=accountById(l.accountId);if(a?.type===type)total += ['asset','expense'].includes(type)?cleanNum(l.debit)-cleanNum(l.credit):cleanNum(l.credit)-cleanNum(l.debit);}));return total; }
function cashMovement(month) { const cashIds=accounts().filter(a=>a.type==='asset'&&/kas|bank/i.test(a.name)).map(a=>a.id); let incoming=0,outgoing=0; journals().filter(j=>sameMonth(j.date,month)).forEach(j=>linesFor(j.id).filter(l=>cashIds.includes(l.accountId)).forEach(l=>{const net=cleanNum(l.debit)-cleanNum(l.credit);if(net>=0)incoming+=net;else outgoing+=Math.abs(net);})); return {incoming,outgoing}; }

function accountOnlyBootstrap(data) {
  // Never hydrate finance records returned by an old plaintext account backend.
  // Production finance data belongs only in the user's Google Drive workbook.
  if (!getApiUrl()) return data;
  return {...data, books:[], members:[], accounts:[], journals:[], journalLines:[], budgets:[], audit:[]};
}
async function preferredBootstrap(fallback) {
  const accountData=accountOnlyBootstrap(fallback), drive=driveStorage();
  if (!drive || !accountData?.user) return accountData;
  const data=await drive.resume(accountData.user);
  return data || accountData;
}
async function connectGoogleDrive() {
  if (!state.user) { toast('Masuk ke akun CatatRapi terlebih dahulu.','error'); return; }
  const drive=driveStorage();
  if (!drive) { toast('Komponen Google Drive belum dimuat. Periksa koneksi lalu muat ulang halaman.','error'); return; }
  const buttons=$$('[data-connect-drive]'); buttons.forEach(button=>{button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Menghubungkan…';});
  try {
    const data=await drive.connect(state.user);
    hydrate(data);
    localStorage.removeItem(DB_KEY);
    showApp();
    toast('Google Drive pribadi terhubung. Data keuangan tersimpan di file Anda sendiri.','success');
  } catch(error) {
    toast(error.message||'Google Drive belum dapat dihubungkan.','error');
    renderStorageConnection();
  } finally {
    buttons.forEach(button=>{button.disabled=false;button.textContent=isDriveMode()?'Perbarui akses Google Drive':(button.dataset.originalText||'Hubungkan Google Drive');});
  }
}
async function boot() {
  bindStaticEvents();
  const session=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');
  if(session){state.token=session.token;try{const data=await preferredBootstrap(await api('bootstrap'));hydrate(data);showApp();}catch(e){sessionStorage.removeItem(SESSION_KEY);toast('Sesi tidak dapat diteruskan. Silakan masuk lagi.','error');}}
}
function bindStaticEvents() {
  $$('[data-auth-tab]').forEach(btn=>btn.addEventListener('click',()=>switchAuth(btn.dataset.authTab)));
  $('#login-form').addEventListener('submit', loginSubmit); $('#register-form').addEventListener('submit', registerSubmit); $('#demo-login').addEventListener('click', demoLogin);
  $$('.nav-item[data-view]').forEach(btn=>btn.addEventListener('click',()=>setView(btn.dataset.view)));
  $$('[data-go-view]').forEach(btn=>btn.addEventListener('click',()=>setView(btn.dataset.goView)));
  $('#logout-btn').addEventListener('click', logout); $('#book-switcher').addEventListener('click',()=>$('#book-menu').classList.toggle('hidden')); $('#create-book-btn').addEventListener('click',()=>openModal('book')); $('#new-transaction-btn').addEventListener('click',()=>openModal('transaction')); $('#new-transaction-top').addEventListener('click',()=>openModal('transaction')); document.addEventListener('click',event=>{const button=event.target.closest('[data-open-modal]');if(button)openModal(button.dataset.openModal);});
  $('#transaction-search').addEventListener('input',renderTransactions); $('#transaction-period').addEventListener('change',renderTransactions); $('#export-journal').addEventListener('click',exportJournal);
  $$('.account-type-card').forEach(btn=>btn.addEventListener('click',()=>{state.accountFilter=btn.dataset.accountFilter;$$('.account-type-card').forEach(x=>x.classList.toggle('active',x===btn));renderAccounts();}));
  $$('.report-tab').forEach(btn=>btn.addEventListener('click',()=>{state.report=btn.dataset.report;$$('.report-tab').forEach(x=>x.classList.toggle('active',x===btn));renderReport();})); $('#report-date').addEventListener('change',renderReport); $('#print-report').addEventListener('click',()=>window.print());
  $('#invite-member').addEventListener('click',()=>openModal('member'));
  $('#connect-drive-btn').addEventListener('click',connectGoogleDrive); $('#connect-drive-dashboard').addEventListener('click',connectGoogleDrive); $('#open-drive-file-btn').addEventListener('click',()=>{const id=driveStorage()?.activeFileId();if(id)window.open(`https://docs.google.com/spreadsheets/d/${encodeURIComponent(id)}/edit`,'_blank','noopener');});
  $('#open-sidebar').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#sidebar-backdrop').classList.add('show');}); $('#close-sidebar').addEventListener('click',closeSidebar); $('#sidebar-backdrop').addEventListener('click',closeSidebar);
  $('#modal-root').addEventListener('click',e=>{if(e.target.closest('[data-close-modal]')) closeModal();});
}
function switchAuth(tab){$$('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b.dataset.authTab===tab));$('#login-form').classList.toggle('hidden',tab!=='login');$('#register-form').classList.toggle('hidden',tab!=='register');}
async function loginSubmit(e){e.preventDefault();driveStorage()?.deactivate();const username=$('#login-username').value.trim(),pin=$('#login-pin').value;try{const r=await api('login',{username,pin});state.token=r.token;sessionStorage.setItem(SESSION_KEY,JSON.stringify({token:r.token,username:r.user.username,userId:r.user.id}));const data=await preferredBootstrap(await api('bootstrap'));hydrate(data);showApp();toast(isDriveMode()?'Selamat datang kembali, '+state.user.name+'.':'Selamat datang, '+state.user.name+'. Hubungkan Google Drive untuk membuka data keuangan Anda.',isDriveMode()?'success':'');}catch(err){toast(err.message,'error');}}
async function registerSubmit(e){e.preventDefault();driveStorage()?.deactivate();const name=$('#register-name').value.trim(),username=$('#register-username').value.trim(),pin=$('#register-pin').value,confirm=$('#register-pin-confirm').value;if(pin!==confirm){toast('Konfirmasi PIN tidak sama.','error');return;}try{await api('register',{name,username,pin});const r=await api('login',{username,pin});state.token=r.token;sessionStorage.setItem(SESSION_KEY,JSON.stringify({token:r.token,username:r.user.username,userId:r.user.id}));hydrate(await api('bootstrap'));showApp();toast('Akun berhasil dibuat. Hubungkan Google Drive untuk membuat file keuangan pribadi Anda.','success');}catch(err){toast(err.message,'error');}}
async function demoLogin(){try{state.db=loadLocalDb();let demo=state.db.users.find(u=>u.username==='demo');if(!demo){const salt=randomSalt();state.db.users.push({id:'usr_demo',name:'Rani Pratama',username:'demo',salt,verifier:await hashPin('123456',salt),active:true,createdAt:new Date().toISOString()});const book=createLocalBook('usr_demo','Keuangan Pribadi Rani','personal',new Date().getFullYear());seedDemo(book.id);saveLocalDb();}$('#login-username').value='demo';$('#login-pin').value='123456';$('#login-form').requestSubmit();}catch(err){toast(err.message,'error');}}
function seedDemo(bookId){const acc=(code)=>state.db.accounts.find(a=>a.bookId===bookId&&a.code===code)?.id;const add=(date,desc,ref,rows)=>{const j={id:uid('jrn'),bookId,date,reference:ref,description:desc,status:'posted',createdBy:'usr_demo',createdAt:date+'T08:00:00.000Z'};state.db.journals.push(j);rows.forEach(([code,debit,credit])=>state.db.journalLines.push({id:uid('lin'),journalId:j.id,bookId,accountId:acc(code),debit,credit,memo:''}));}; const now=new Date();const m=offset=>{const d=new Date(now.getFullYear(),now.getMonth()+offset,Math.min(8,now.getDate()));return isoDate(d)}; add(m(-5),'Setoran modal awal','MOD-001',[['1100',25000000,0],['3100',0,25000000]]);add(m(-4),'Pembayaran sewa tempat tinggal','EXP-001',[['6100',1800000,0],['1100',0,1800000]]);add(m(-3),'Pendapatan pekerjaan lepas','INV-001',[['1110',6500000,0],['4100',0,6500000]]);add(m(-2),'Pembayaran internet dan listrik','EXP-008',[['6200',520000,0],['1110',0,520000]]);add(m(-1),'Pendapatan usaha sampingan','INV-011',[['1110',4800000,0],['4100',0,4800000]]);add(m(0),'Pembelian perlengkapan kerja','EXP-015',[['6400',725000,0],['1100',0,725000]]);add(m(0),'Pendapatan pekerjaan proyek','INV-018',[['1110',7200000,0],['4100',0,7200000]]);state.db.budgets.push({id:uid('bud'),bookId,accountId:acc('6100'),month:currentMonth(),amount:2200000,note:'Sewa bulanan'},{id:uid('bud'),bookId,accountId:acc('6200'),month:currentMonth(),amount:750000,note:'Tagihan rutin'},{id:uid('bud'),bookId,accountId:acc('6400'),month:currentMonth(),amount:1500000,note:'Mobilitas'});}
async function logout(){try{await api('logout');}catch{}driveStorage()?.deactivate();sessionStorage.removeItem(SESSION_KEY);state.user=null;state.token=null;state.db=null;$('#app-shell').classList.add('hidden');$('#auth-screen').classList.remove('hidden');$('#login-form').reset();closeSidebar();}
function renderStorageConnection(){const drive=isDriveMode(),demo=!getApiUrl();const notice=$('#drive-required-notice'),stateBox=$('#drive-connection-state'),copy=$('#drive-connection-copy'),connect=$('#connect-drive-btn'),open=$('#open-drive-file-btn');if(notice)notice.classList.toggle('hidden',drive||demo);if(stateBox){stateBox.innerHTML=drive?'<span class="status-dot connected"></span><div><b>Terhubung ke Google Drive pribadi</b><small>File ini dimiliki oleh akun Google Anda; CatatRapi tidak menerima isi jurnal.</small></div>':'<span class="status-dot pending"></span><div><b>Belum terhubung</b><small>Hubungkan Drive sebelum mulai menyimpan data keuangan.</small></div>';}if(copy)copy.textContent=drive?'Data jurnal dibaca dan ditulis langsung dari file Google Drive Anda.':'Hubungkan sekali untuk membuat file CatatRapi di Google Drive Anda.';if(connect){connect.textContent=drive?'Perbarui akses Google Drive':'Hubungkan Google Drive';connect.classList.toggle('hidden',demo);}if(open){const id=driveStorage()?.activeFileId();open.classList.toggle('hidden',!drive||!id);}$('#connection-status').className=`connection ${drive?'live':'local'}`;$('#connection-status').textContent=connectionLabel();}
function showApp(){$('#auth-screen').classList.add('hidden');$('#app-shell').classList.remove('hidden');$('#current-user-name').textContent=state.user.name;$('#user-initials').textContent=initials(state.user.name);$('#current-user-role').textContent=roleLabel(currentRole());$('#report-date').value=isoDate();renderAll();}
function renderAll(){renderStorageConnection();renderBookMenu();renderDashboard();renderTransactions();renderAccounts();renderBudget();renderReport();renderMembers();$('#breadcrumb-book').textContent=activeBook()?.name||'Buku';$('#active-book-name').textContent=activeBook()?.name||'Belum ada buku';}
function setView(view){state.currentView=view;$$('.view').forEach(x=>x.classList.toggle('active-view',x.id===`view-${view}`));$$('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const titles={dashboard:'Ringkasan',transactions:'Jurnal transaksi',accounts:'Daftar akun',budget:'Anggaran',reports:'Laporan',members:'Akses & anggota',settings:'Pengaturan data'};$('#page-title').textContent=titles[view];closeSidebar();if(view==='dashboard')renderDashboard();if(view==='transactions')renderTransactions();if(view==='accounts')renderAccounts();if(view==='budget')renderBudget();if(view==='reports')renderReport();if(view==='members')renderMembers();}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebar-backdrop').classList.remove('show');}
function renderBookMenu(){const book=activeBook();let html=state.db.books.map(b=>`<button data-book-id="${b.id}" class="${b.id===book?.id?'active':''}"><b>${escapeHTML(b.name)}</b><small>${escapeHTML(typeLabelBook(b.type))} · ${b.year}</small></button>`).join('');html+='<hr><button class="new-book-menu" data-new-book>＋ Buat buku baru</button>';$('#book-menu').innerHTML=html;$$('[data-book-id]').forEach(btn=>btn.addEventListener('click',()=>{state.activeBookId=btn.dataset.bookId;localStorage.setItem('catatrapi_active_book',state.activeBookId);$('#book-menu').classList.add('hidden');renderAll();}));$('[data-new-book]').addEventListener('click',()=>{ $('#book-menu').classList.add('hidden');openModal('book');});}
function typeLabelBook(type){return ({personal:'Pribadi',business:'Bisnis',project:'Proyek',family:'Keluarga',other:'Lainnya'})[type]||type;}
function renderDashboard(){if(!activeBook())return;const cash=accounts().filter(a=>a.type==='asset'&&/kas|bank/i.test(a.name)).reduce((s,a)=>s+balanceOf(a.id),0),income=monthlyActivity('income'),expense=monthlyActivity('expense'),networth=accountBalanceByType('asset')-accountBalanceByType('liability');$('#stat-cash').textContent=rupiah(cash);$('#stat-income').textContent=rupiah(income);$('#stat-expense').textContent=rupiah(expense);$('#stat-networth').textContent=rupiah(networth);$('#stat-income-sub').textContent=`${monthLabel(currentMonth())}`;$('#stat-expense-sub').textContent=`${monthLabel(currentMonth())}`;$('#dashboard-period').textContent=`Periode ${monthLabel(currentMonth())} · ${activeBook().name}`;renderChart();renderHealth();renderRecent();const diff=income-expense;$('#insight-title').textContent=diff>=0?'Arus operasional bulan ini positif.':'Pengeluaran bulan ini lebih tinggi.';$('#insight-body').textContent=diff>=0?`Selisih pendapatan dan beban adalah ${rupiah(diff)}. Pastikan transaksi lain juga sudah dijurnal.`:`Defisit operasional sementara sebesar ${rupiah(Math.abs(diff))}. Tinjau pos beban dan anggaran Anda.`;}
function monthLabel(month){const [y,m]=month.split('-');return new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(new Date(Number(y),Number(m)-1,1));}
function renderChart(){let html='';const now=new Date();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1),key=isoDate(d).slice(0,7),flow=cashMovement(key),largest=Math.max(1,flow.incoming,flow.outgoing);html+=`<div class="chart-col" title="${monthLabel(key)}: masuk ${rupiah(flow.incoming)}, keluar ${rupiah(flow.outgoing)}"><i class="chart-bar in" style="height:${Math.max(2,flow.incoming/largest*155)}px"></i><i class="chart-bar out" style="height:${Math.max(2,flow.outgoing/largest*155)}px"></i><span class="chart-label">${monthFmt.format(d)}</span></div>`;}$('#cashflow-chart').innerHTML=html;}
function renderHealth(){const rows=[['Aset','asset'],['Kewajiban','liability'],['Ekuitas','equity'],['Pendapatan','income']].map(([label,type])=>({label,value:accountBalanceByType(type)}));const max=Math.max(1,...rows.map(x=>Math.abs(x.value)));$('#account-health-list').innerHTML=rows.map(r=>`<div class="health-row"><div class="health-head"><span>${r.label}</span><b>${rupiah(r.value)}</b></div><div class="progress"><i style="width:${Math.min(100,Math.abs(r.value)/max*100)}%"></i></div></div>`).join('');}
function renderRecent(){const latest=journals().filter(j=>j.status==='posted').slice(0,5);$('#recent-transactions').innerHTML=latest.length?latest.map(j=>{const lines=linesFor(j.id),debit=lines.reduce((s,l)=>s+cleanNum(l.debit),0);return `<div class="mini-tx"><span class="tx-glyph">⇄</span><div><strong>${escapeHTML(j.description)}</strong><small>${fullDateFmt.format(journalDate(j.date))} · ${escapeHTML(j.reference||'Jurnal umum')}</small></div><b>${rupiah(debit)}</b></div>`}).join(''):'<div class="empty-state"><span>⇄</span><h3>Belum ada jurnal</h3><p>Catat transaksi pertama Anda.</p></div>';}
function canCorrectJournal(journal){const role=currentRole();return journal.status==='posted'&&(role==='owner'||(role==='editor'&&journal.createdBy===state.user.id));}
function replaceJournalState(journal){const index=state.db.journals.findIndex(item=>item.id===journal.id);if(index>=0)state.db.journals[index]=journal;else state.db.journals.push(journal);}
function renderTransactions(){if(!activeBook())return;let items=journals().filter(j=>j.status!=='reversal'),query=$('#transaction-search')?.value?.trim().toLowerCase()||'',period=$('#transaction-period')?.value||'all';if(period==='month')items=items.filter(j=>sameMonth(j.date));if(period==='year')items=items.filter(j=>dateKey(j.date).startsWith(String(new Date().getFullYear())));if(query)items=items.filter(j=>`${j.description} ${j.reference} ${j.voidReason||''} ${linesFor(j.id).map(l=>accountById(l.accountId)?.name||'').join(' ')}`.toLowerCase().includes(query));const body=$('#transactions-table'),empty=$('#transactions-empty');body.innerHTML=items.map(j=>{const lines=linesFor(j.id),debit=lines.reduce((s,l)=>s+cleanNum(l.debit),0),names=lines.map(l=>accountById(l.accountId)?.name||'Akun').join(' '),voided=j.status==='voided',status=voided?'<span class="status-pill voided">Dibatalkan</span>':'<span class="status-pill">Dibukukan</span>',actions=canCorrectJournal(j)?`<button class="tx-action-btn" title="Koreksi transaksi" data-correct-journal="${j.id}">Ubah</button><button class="tx-action-btn danger" title="Batalkan transaksi" data-void-journal="${j.id}">Batal</button>`:'';return `<tr class="${voided?'voided-row':''}"><td><strong>${fullDateFmt.format(journalDate(j.date))}</strong></td><td><strong>${escapeHTML(j.description)}</strong><small>${voided?'Alasan: '+escapeHTML(j.voidReason||'—'):escapeHTML(j.reference||'—')}</small></td><td><span title="${escapeHTML(names)}">${escapeHTML(names.length>55?names.slice(0,55)+'…':names)}</span></td><td class="right money">${rupiah(debit)}</td><td class="right money">${rupiah(debit)}</td><td>${status}</td><td><div class="tx-actions"><button class="tx-view-btn" title="Lihat detail" data-journal-detail="${j.id}">›</button>${actions}</div></td></tr>`;}).join('');empty.classList.toggle('hidden',items.length>0);$$('[data-journal-detail]').forEach(b=>b.addEventListener('click',()=>showJournalDetail(b.dataset.journalDetail)));$$('[data-correct-journal]').forEach(b=>b.addEventListener('click',()=>openModal('journal',{correctionOf:b.dataset.correctJournal})));$$('[data-void-journal]').forEach(b=>b.addEventListener('click',()=>voidJournal(b.dataset.voidJournal)));}
async function voidJournal(journalId){const journal=state.db.journals.find(item=>item.id===journalId);if(!journal)return;const reason=window.prompt(`Alasan membatalkan transaksi “${journal.description}”:`);if(reason===null)return;if(reason.trim().length<3){toast('Isi alasan pembatalan minimal 3 karakter.','error');return;}if(!window.confirm('Batalkan transaksi ini? CatatRapi akan membuat jurnal pembalik; data asli tidak dihapus.'))return;try{const result=await api('voidJournal',{bookId:journal.bookId,journalId,reason:reason.trim()});replaceJournalState(result.journal);state.db.journals.push(result.reversal);state.db.journalLines.push(...result.reversalLines);renderAll();toast('Transaksi dibatalkan melalui jurnal pembalik.','success');}catch(error){toast(error.message||'Transaksi gagal dibatalkan.','error');}}
function renderAccounts(){if(!activeBook())return;const all=accounts();$('#all-accounts-count').textContent=all.length;['asset','liability','equity'].forEach(t=>{const el=$(`#${t}-balance`);if(el)el.textContent=rupiah(accountBalanceByType(t));});const listed=state.accountFilter==='all'?all:all.filter(a=>a.type===state.accountFilter);$('#accounts-table').innerHTML=listed.map(a=>`<tr><td><strong>${a.code}</strong></td><td><strong>${escapeHTML(a.name)}</strong></td><td><span class="group-pill ${a.type}">${typeLabel(a.type)}</span></td><td>${normalSide(a.type)}</td><td class="right money">${rupiah(balanceOf(a.id))}</td><td><span class="status-pill">Aktif</span></td></tr>`).join('');}
function renderBudget(){if(!activeBook())return;const bs=state.db.budgets.filter(b=>b.bookId===state.activeBookId&&b.month===currentMonth());let total=0,actualTotal=0;const rows=bs.map(b=>{const a=accountById(b.accountId),actual=monthlyAccountExpense(b.accountId),amount=cleanNum(b.amount);total+=amount;actualTotal+=actual;return {b,a,actual,amount};});$('#budget-total').textContent=rupiah(total);$('#budget-actual').textContent=rupiah(actualTotal);$('#budget-remaining').textContent=rupiah(total-actualTotal);$('#budget-list').innerHTML=rows.map(({b,a,actual,amount})=>{const pct=Math.min(100,actual/Math.max(amount,1)*100);return `<div class="budget-row"><div><strong>${escapeHTML(a?.name||'Akun')}</strong><small>${escapeHTML(b.note||'Anggaran '+monthLabel(b.month))}</small></div><div class="budget-track"><i class="${actual>amount?'over':''}" style="width:${pct}%"></i></div><div class="budget-money"><b>${rupiah(actual)}</b><small> / ${rupiah(amount)}</small></div></div>`;}).join('');$('#budget-empty').classList.toggle('hidden',rows.length>0);}
function monthlyAccountExpense(accountId,month=currentMonth()){let total=0;journals().filter(j=>sameMonth(j.date,month)).forEach(j=>linesFor(j.id).filter(l=>l.accountId===accountId).forEach(l=>total+=cleanNum(l.debit)-cleanNum(l.credit)));return total;}
function renderReport(){if(!activeBook())return;const cutoff=$('#report-date').value||isoDate(),book=activeBook();let content='';if(state.report==='income')content=incomeReport(cutoff);if(state.report==='position')content=positionReport(cutoff);if(state.report==='trial')content=trialReport(cutoff);if(state.report==='cashflow')content=cashReport(cutoff);$('#report-content').innerHTML=`<div class="report-brand"><img src="assets/catatrapi-crp-logo-web.png" alt="Logo CatatRapi" /><div><strong>CatatRapi</strong><span>Keuangan rapi, keputusan lebih pasti.</span></div></div><div class="report-title"><p>${escapeHTML(book.name)}</p><h2>${({income:'Laporan laba rugi',position:'Laporan posisi keuangan',trial:'Neraca saldo',cashflow:'Laporan arus kas'})[state.report]}</h2><p>Per ${fullDateFmt.format(new Date(cutoff+'T00:00:00'))} · Mata uang Rupiah</p></div>${content}`;}
function reportRows(type,cutoff){return accounts().filter(a=>a.type===type).map(a=>({name:a.name,value:balanceOf(a.id,cutoff)})).filter(x=>x.value!==0);}
function linesHtml(rows){return rows.length?rows.map(r=>`<div class="report-line indent"><span>${escapeHTML(r.name)}</span><span class="money">${rupiah(r.value)}</span></div>`).join(''):'<div class="report-line indent"><span>Tidak ada saldo</span><span class="money">Rp0</span></div>';}
function totalRows(rows){return rows.reduce((s,r)=>s+r.value,0)}
function incomeReport(c){const inc=reportRows('income',c),exp=reportRows('expense',c),income=totalRows(inc),expense=totalRows(exp),net=income-expense;return `<div class="report-section"><h3>PENDAPATAN</h3>${linesHtml(inc)}<div class="report-line total"><span>Total pendapatan</span><span class="money">${rupiah(income)}</span></div></div><div class="report-section"><h3>BEBAN</h3>${linesHtml(exp)}<div class="report-line total"><span>Total beban</span><span class="money">${rupiah(expense)}</span></div></div><div class="report-line grand-total"><span>${net>=0?'LABA BERSIH':'RUGI BERSIH'}</span><span class="money">${rupiah(Math.abs(net))}</span></div>`;}
function positionReport(c){const asset=reportRows('asset',c),liab=reportRows('liability',c),equity=reportRows('equity',c),a=totalRows(asset),l=totalRows(liab),e=totalRows(equity),retained=totalRows(reportRows('income',c))-totalRows(reportRows('expense',c));return `<div class="report-section"><h3>ASET</h3>${linesHtml(asset)}<div class="report-line total"><span>Total aset</span><span class="money">${rupiah(a)}</span></div></div><div class="report-section"><h3>KEWAJIBAN</h3>${linesHtml(liab)}<div class="report-line total"><span>Total kewajiban</span><span class="money">${rupiah(l)}</span></div></div><div class="report-section"><h3>EKUITAS</h3>${linesHtml(equity)}<div class="report-line indent"><span>Laba (rugi) berjalan</span><span class="money">${rupiah(retained)}</span></div><div class="report-line total"><span>Total ekuitas</span><span class="money">${rupiah(e+retained)}</span></div></div><div class="report-line grand-total"><span>Total kewajiban & ekuitas</span><span class="money">${rupiah(l+e+retained)}</span></div>`;}
function trialReport(c){const rows=accounts().map(a=>({a,bal:balanceOf(a.id,c)})).filter(x=>x.bal!==0);const debit=rows.filter(x=>['asset','expense'].includes(x.a.type)).reduce((s,x)=>s+x.bal,0),credit=rows.filter(x=>!['asset','expense'].includes(x.a.type)).reduce((s,x)=>s+x.bal,0);return `<div class="report-section"><h3>DAFTAR SALDO AKUN</h3>${rows.map(x=>`<div class="report-line"><span>${escapeHTML(x.a.code)} · ${escapeHTML(x.a.name)}</span><span class="money">${['asset','expense'].includes(x.a.type)?rupiah(x.bal)+' D':rupiah(x.bal)+' K'}</span></div>`).join('')||'<div class="report-line"><span>Belum ada saldo</span><span>—</span></div>'}<div class="report-line grand-total"><span>Total debit / kredit</span><span class="money">${rupiah(debit)} / ${rupiah(credit)}</span></div></div>`;}
function cashReport(c){const date=new Date(c+'T00:00:00'),month=c.slice(0,7),flow=cashMovement(month),cash=accounts().filter(a=>a.type==='asset'&&/kas|bank/i.test(a.name)).reduce((s,a)=>s+balanceOf(a.id,c),0);return `<div class="report-section"><h3>AKTIVITAS OPERASI — ${monthLabel(month)}</h3><div class="report-line"><span>Penerimaan kas dan bank</span><span class="money">${rupiah(flow.incoming)}</span></div><div class="report-line"><span>Pengeluaran kas dan bank</span><span class="money">(${rupiah(flow.outgoing)})</span></div><div class="report-line total"><span>Arus kas bersih periode</span><span class="money">${rupiah(flow.incoming-flow.outgoing)}</span></div></div><div class="report-line grand-total"><span>Saldo kas & bank pada ${fullDateFmt.format(date)}</span><span class="money">${rupiah(cash)}</span></div><p class="field-hint">Laporan arus kas versi awal ini berasal dari pergerakan akun Kas dan Bank. Klasifikasi operasi, investasi, dan pendanaan dapat dikembangkan pada fase berikutnya.</p>`;}
function openModal(kind, detail=null){const root=$('#modal-root'),templates={transaction:'transaction-template',journal:'journal-template',book:'book-template',account:'account-template',budget:'budget-template',member:'member-template'};const titles={transaction:['TRANSAKSI BARU','Catat transaksi'],journal:['JURNAL MANUAL','Jurnal penyesuaian'],book:['BUKU PENCATATAN','Buat buku baru'],account:['CHART OF ACCOUNTS','Tambah akun'],budget:['PERENCANAAN','Tetapkan anggaran'],member:['KOLABORASI','Undang anggota']};$('#modal-eyebrow').textContent=titles[kind][0];$('#modal-title').textContent=titles[kind][1];$('#modal-content').innerHTML=$(`#${templates[kind]}`).innerHTML;root.classList.remove('hidden');root.setAttribute('aria-hidden','false');if(kind==='transaction')setupTransactionForm();if(kind==='journal')setupJournalForm(detail);if(kind==='book')setupBookForm();if(kind==='account')setupAccountForm();if(kind==='budget')setupBudgetForm();if(kind==='member')setupMemberForm();}
function closeModal(){$('#modal-root').classList.add('hidden');$('#modal-root').setAttribute('aria-hidden','true');}
function liquidAccounts(){const assetAccounts=accounts().filter(a=>a.type==='asset');const cashOrBank=assetAccounts.filter(a=>/kas|bank/i.test(a.name));return cashOrBank.length?cashOrBank:assetAccounts;}
function quickAccountOptions(list,selectedId=''){return '<option value="">Pilih akun</option>'+list.map(a=>`<option value="${a.id}" ${a.id===selectedId?'selected':''}>${escapeHTML(a.code)} — ${escapeHTML(a.name)}</option>`).join('');}
function preferredQuickAccount(list,matcher){return list.find(a=>matcher.test(a.name))?.id||list[0]?.id||'';}
function setupTransactionForm(){if(!canEdit()){toast('Akses Anda hanya untuk membaca.','error');closeModal();return;}$('#quick-date').value=isoDate();renderQuickAccountFields();$$('[data-quick-type]').forEach(button=>button.addEventListener('click',()=>{const type=button.dataset.quickType;$('#quick-transaction-type').value=type;$$('[data-quick-type]').forEach(item=>item.classList.toggle('active',item===button));renderQuickAccountFields();}));$('#simple-transaction-form').addEventListener('input',renderQuickJournalPreview);$('#simple-transaction-form').addEventListener('change',renderQuickJournalPreview);$('#simple-transaction-form').addEventListener('submit',submitSimpleTransaction);$('#open-manual-journal').addEventListener('click',()=>{closeModal();openModal('journal');});}
function renderQuickAccountFields(){const type=$('#quick-transaction-type').value,cashAccounts=liquidAccounts();if(type==='transfer'){const sourceId=preferredQuickAccount(cashAccounts,/kas/i),destinationId=cashAccounts.find(a=>a.id!==sourceId)?.id||'';$('#quick-account-fields').innerHTML=`<div class="form-grid two"><label>Dari akun<select id="quick-source-account">${quickAccountOptions(cashAccounts,sourceId)}</select></label><label>Ke akun<select id="quick-destination-account">${quickAccountOptions(cashAccounts,destinationId)}</select></label></div>`;}else{const categoryType=type==='income'?'income':'expense',categories=accounts().filter(a=>a.type===categoryType),cashLabel=type==='income'?'Dana diterima di':'Bayar dari',categoryLabel=type==='income'?'Kategori pemasukan':'Kategori pengeluaran',cashId=preferredQuickAccount(cashAccounts,/kas/i),categoryId=preferredQuickAccount(categories,type==='income'?/pendapatan usaha/i:/beban lain/i);$('#quick-account-fields').innerHTML=`<div class="form-grid two"><label>${cashLabel}<select id="quick-cash-account">${quickAccountOptions(cashAccounts,cashId)}</select></label><label>${categoryLabel}<select id="quick-category-account">${quickAccountOptions(categories,categoryId)}</select></label></div>`;}renderQuickJournalPreview();}
function renderQuickJournalPreview(){const preview=$('#quick-journal-preview');if(!preview)return;const type=$('#quick-transaction-type').value,amount=cleanNum($('#quick-amount')?.value),cash=accountById($('#quick-cash-account')?.value),category=accountById($('#quick-category-account')?.value),source=accountById($('#quick-source-account')?.value),destination=accountById($('#quick-destination-account')?.value);if(!amount){preview.innerHTML='<span class="preview-icon">⇄</span><span>Masukkan nominal untuk melihat jurnal otomatis.</span>';return;}if(type==='income'&&cash&&category){preview.innerHTML=`<span class="preview-icon income">↗</span><span><b>Otomatis:</b> Debit ${escapeHTML(cash.name)} ${rupiah(amount)} · Kredit ${escapeHTML(category.name)} ${rupiah(amount)}</span>`;return;}if(type==='expense'&&cash&&category){preview.innerHTML=`<span class="preview-icon expense">↘</span><span><b>Otomatis:</b> Debit ${escapeHTML(category.name)} ${rupiah(amount)} · Kredit ${escapeHTML(cash.name)} ${rupiah(amount)}</span>`;return;}if(type==='transfer'&&source&&destination){preview.innerHTML=`<span class="preview-icon transfer">⇄</span><span><b>Otomatis:</b> Debit ${escapeHTML(destination.name)} ${rupiah(amount)} · Kredit ${escapeHTML(source.name)} ${rupiah(amount)}</span>`;return;}preview.innerHTML='<span class="preview-icon">!</span><span>Pilih akun yang digunakan terlebih dahulu.</span>';}
function buildSimpleJournal(){const type=$('#quick-transaction-type').value,amount=cleanNum($('#quick-amount').value),cashId=$('#quick-cash-account')?.value,categoryId=$('#quick-category-account')?.value,sourceId=$('#quick-source-account')?.value,destinationId=$('#quick-destination-account')?.value;if(!$('#quick-date').value)throw new Error('Pilih tanggal transaksi terlebih dahulu.');if(!$('#quick-description').value.trim())throw new Error('Isi deskripsi transaksi terlebih dahulu.');if(amount<=0)throw new Error('Masukkan nominal transaksi yang lebih dari Rp0.');if(type==='income'){if(!cashId||!categoryId)throw new Error('Pilih rekening penerimaan dan kategori pemasukan.');return [{accountId:cashId,debit:amount,credit:0},{accountId:categoryId,debit:0,credit:amount}];}if(type==='expense'){if(!cashId||!categoryId)throw new Error('Pilih rekening pembayaran dan kategori pengeluaran.');return [{accountId:categoryId,debit:amount,credit:0},{accountId:cashId,debit:0,credit:amount}];}if(!sourceId||!destinationId)throw new Error('Pilih akun asal dan akun tujuan transfer.');if(sourceId===destinationId)throw new Error('Akun asal dan tujuan transfer harus berbeda.');return [{accountId:destinationId,debit:amount,credit:0},{accountId:sourceId,debit:0,credit:amount}];}
async function submitSimpleTransaction(event){event.preventDefault();let lines;try{lines=buildSimpleJournal();}catch(error){toast(error.message,'error');return;}const saveButton=$('#save-simple-transaction');saveButton.disabled=true;saveButton.textContent='Menyimpan…';const data={bookId:state.activeBookId,date:$('#quick-date').value,reference:'',description:$('#quick-description').value.trim(),lines};try{const result=await api('createJournal',data);state.db.journals.push(result.journal);state.db.journalLines.push(...result.lines);closeModal();renderAll();toast('Transaksi tersimpan. Jurnal berpasangan dibuat otomatis.','success');}catch(error){toast(error.message||'Transaksi gagal disimpan.','error');saveButton.disabled=false;saveButton.textContent='Simpan transaksi';}}
function setupJournalForm(detail=null){if(!canEdit()){toast('Akses Anda hanya untuk membaca.','error');closeModal();return;}const form=$('#journal-form'),originalId=detail?.correctionOf,original=originalId?state.db.journals.find(j=>j.id===originalId):null;if(originalId&&!original){toast('Transaksi yang akan dikoreksi tidak ditemukan.','error');closeModal();return;}if(original&&!canCorrectJournal(original)){toast('Anda tidak memiliki hak untuk mengoreksi transaksi ini.','error');closeModal();return;}if(original){form.dataset.correctionOf=original.id;$('#modal-eyebrow').textContent='KOREKSI TRANSAKSI';$('#modal-title').textContent='Koreksi jurnal';$('#journal-date').value=original.date;$('#journal-reference').value=original.reference||'';$('#journal-description').value=original.description;const reason=document.createElement('label');reason.className='correction-reason';reason.innerHTML='Alasan koreksi<input id="correction-reason" maxlength="160" placeholder="Contoh: Salah memilih kategori beban" />';$('#journal-description').closest('label').after(reason);linesFor(original.id).forEach(line=>{addJournalLine();const row=$$('.journal-line').at(-1);$('.line-account',row).value=line.accountId;$('.line-debit',row).value=cleanNum(line.debit)||'';$('.line-credit',row).value=cleanNum(line.credit)||'';});$('#save-journal').textContent='Simpan koreksi';}else{$('#journal-date').value=isoDate();addJournalLine();addJournalLine();}recalcJournal();$('#add-journal-line').addEventListener('click',addJournalLine);$('#journal-form').addEventListener('input',recalcJournal);$('#journal-form').addEventListener('change',recalcJournal);$('#journal-form').addEventListener('submit',submitJournal);}
function journalOptions(){return '<option value="">Pilih akun</option>'+accounts().map(a=>`<option value="${a.id}">${escapeHTML(a.code)} — ${escapeHTML(a.name)}</option>`).join('');}
function addJournalLine(){const row=document.createElement('div');row.className='journal-line';row.innerHTML=`<select class="line-account">${journalOptions()}</select><input class="line-debit" type="number" min="0" step="1000" inputmode="numeric" placeholder="Debit" /><input class="line-credit" type="number" min="0" step="1000" inputmode="numeric" placeholder="Kredit" /><button class="delete-line" type="button" aria-label="Hapus baris">×</button>`;$('#journal-lines').append(row);$('.delete-line',row).addEventListener('click',()=>{if($$('.journal-line').length<=2){toast('Jurnal memerlukan minimal dua baris.','error');return;}row.remove();recalcJournal();});}
function journalRows(){return $$('.journal-line').map((row,index)=>({row:index+1,accountId:$('.line-account',row).value,debit:cleanNum($('.line-debit',row).value),credit:cleanNum($('.line-credit',row).value)}));}
function getJournalLines(){return journalRows().filter(l=>l.accountId||l.debit||l.credit);}
function recalcJournal(){const lines=getJournalLines(),debit=lines.reduce((s,l)=>s+cleanNum(l.debit),0),credit=lines.reduce((s,l)=>s+cleanNum(l.credit),0),allComplete=lines.length>=2&&lines.every(l=>l.accountId&&(l.debit>0||l.credit>0)&&!(l.debit>0&&l.credit>0)),balanced=allComplete&&debit>0&&debit===credit;$('#journal-debit-total').textContent=rupiah(debit);$('#journal-credit-total').textContent=rupiah(credit);const st=$('#journal-balance-status');st.textContent=balanced?'Seimbang':'Belum seimbang';st.className=balanced?'balanced':'unbalanced';}
function validateJournalForm(){const date=$('#journal-date').value,description=$('#journal-description').value.trim(),rows=journalRows(),lines=rows.filter(l=>l.accountId||l.debit||l.credit);if(!date){toast('Pilih tanggal transaksi terlebih dahulu.','error');return null;}if(!description){toast('Isi deskripsi transaksi terlebih dahulu.','error');return null;}if(lines.length<2){toast('Tambahkan minimal dua baris jurnal: satu debit dan satu kredit.','error');return null;}const missing=lines.find(l=>!l.accountId);if(missing){toast(`Pilih akun pada baris jurnal ${missing.row}.`,'error');return null;}const emptyAmount=lines.find(l=>l.debit<=0&&l.credit<=0);if(emptyAmount){toast(`Isi nominal debit atau kredit pada baris ${emptyAmount.row}.`,'error');return null;}const bothSides=lines.find(l=>l.debit>0&&l.credit>0);if(bothSides){toast(`Baris ${bothSides.row} hanya boleh berisi debit atau kredit, bukan keduanya.`,'error');return null;}const debit=lines.reduce((sum,l)=>sum+l.debit,0),credit=lines.reduce((sum,l)=>sum+l.credit,0);if(debit!==credit){toast(`Jurnal belum seimbang: debit ${rupiah(debit)}, kredit ${rupiah(credit)}.`,'error');return null;}if(debit<=0){toast('Nominal jurnal harus lebih dari Rp0.','error');return null;}return lines;}
async function submitJournal(e){e.preventDefault();const lines=validateJournalForm();if(!lines)return;const form=$('#journal-form'),correctionOf=form.dataset.correctionOf,reason=$('#correction-reason')?.value.trim();if(correctionOf&&(!reason||reason.length<3)){toast('Isi alasan koreksi minimal 3 karakter.','error');return;}const saveButton=$('#save-journal');saveButton.disabled=true;saveButton.textContent='Menyimpan…';const data={bookId:state.activeBookId,date:$('#journal-date').value,reference:$('#journal-reference').value.trim(),description:$('#journal-description').value.trim(),lines};try{if(correctionOf){const result=await api('correctJournal',{...data,journalId:correctionOf,reason});replaceJournalState(result.original);state.db.journals.push(result.reversal,result.journal);state.db.journalLines.push(...result.reversalLines,...result.lines);closeModal();renderAll();toast('Koreksi tersimpan. Jurnal lama dibalik secara otomatis.','success');}else{const result=await api('createJournal',data);state.db.journals.push(result.journal);state.db.journalLines.push(...result.lines);closeModal();renderAll();toast('Jurnal berhasil dibukukan dan seimbang.','success');}}catch(err){toast(err.message||'Jurnal gagal disimpan. Periksa koneksi server lalu coba kembali.','error');saveButton.disabled=false;saveButton.textContent=correctionOf?'Simpan koreksi':'Simpan jurnal';}}
function setupBookForm(){$('#book-year').value=new Date().getFullYear();$('#book-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('createBook',{name:$('#book-name').value.trim(),type:$('#book-type').value,year:$('#book-year').value});state.db.books.push(r.book);state.db.accounts.push(...r.accounts);state.activeBookId=r.book.id;localStorage.setItem('catatrapi_active_book',r.book.id);closeModal();renderAll();toast('Buku pencatatan baru siap digunakan.','success');}catch(err){toast(err.message,'error');}});}
function setupAccountForm(){$('#account-type').addEventListener('change',e=>$('#normal-balance-note').textContent=['asset','expense'].includes(e.target.value)?'Aset dan beban bersaldo normal debit.':'Kewajiban, ekuitas, dan pendapatan bersaldo normal kredit.');$('#account-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('createAccount',{bookId:state.activeBookId,code:$('#account-code').value.trim(),name:$('#account-name').value.trim(),type:$('#account-type').value});state.db.accounts.push(r.account);closeModal();renderAccounts();toast('Akun baru telah ditambahkan.','success');}catch(err){toast(err.message,'error');}});}
function setupBudgetForm(){$('#budget-month').value=currentMonth();$('#budget-account').innerHTML=accounts().filter(a=>a.type==='expense').map(a=>`<option value="${a.id}">${escapeHTML(a.code)} — ${escapeHTML(a.name)}</option>`).join('');$('#budget-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('createBudget',{bookId:state.activeBookId,accountId:$('#budget-account').value,month:$('#budget-month').value,amount:$('#budget-amount').value,note:$('#budget-note').value.trim()});state.db.budgets=state.db.budgets.filter(x=>x.bookId!==state.activeBookId).concat(r.budgets);closeModal();renderBudget();toast('Anggaran disimpan.','success');}catch(err){toast(err.message,'error');}});}
function setupMemberForm(){if(currentRole()!=='owner'){toast('Hanya pemilik dapat mengundang anggota.','error');closeModal();return;}$('#member-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('shareBook',{bookId:state.activeBookId,username:$('#member-username').value.trim(),role:$('#member-role').value});const existing=state.db.members.findIndex(m=>m.bookId===state.activeBookId&&m.userId===r.member.userId);if(existing>=0)state.db.members[existing]=r.member;else state.db.members.push(r.member);if(!state.db.users.find(u=>u.id===r.user.id))state.db.users.push(r.user);closeModal();renderMembers();toast('Akses anggota berhasil diperbarui.','success');}catch(err){toast(err.message,'error');}});}
function showJournalDetail(id){const j=state.db.journals.find(x=>x.id===id);if(!j)return;const rows=linesFor(id).map(l=>{const a=accountById(l.accountId);return `<div class="report-line"><span>${escapeHTML(a?.code||'')} · ${escapeHTML(a?.name||'')}</span><span class="money">${cleanNum(l.debit)>0?'Debit '+rupiah(l.debit):'Kredit '+rupiah(l.credit)}</span></div>`;}).join(''),voided=j.status==='voided',note=voided?`<b>Transaksi dibatalkan</b><p>Alasan: ${escapeHTML(j.voidReason||'—')}. Jurnal pembalik dibuat otomatis agar audit trail tetap tersimpan.</p>`:'<b>Transaksi dibukukan</b><p>Jurnal berpasangan tersimpan dan memengaruhi laporan keuangan.</p>';$('#modal-eyebrow').textContent='DETAIL JURNAL';$('#modal-title').textContent=j.description;$('#modal-content').innerHTML=`<div class="modal-form"><div class="info-box"><b>${fullDateFmt.format(journalDate(j.date))}${j.reference?' · '+escapeHTML(j.reference):''}</b><p>${voided?'Status: Dibatalkan':'Status: Dibukukan'}</p></div><div class="info-box ${voided?'voided-info':''}">${note}</div>${rows}<div class="modal-actions"><button class="primary-btn" data-close-modal>Tutup</button></div></div>`;$('#modal-root').classList.remove('hidden');}
function renderMembers(){if(!activeBook())return;if(isDriveMode()){ $('#members-list').innerHTML='<div class="member-drive-note"><b>Berbagi buku belum diaktifkan untuk mode satu Spreadsheet.</b><p>Berbagi file Google Drive akan memberi akses ke semua buku di file tersebut. CatatRapi akan memakai file per buku saat kolaborasi Drive diaktifkan agar akses tetap terbatas.</p></div>';$('#invite-member').disabled=true;return;}const book=activeBook(),all=[{userId:book.ownerId,role:'owner'}].concat(state.db.members.filter(m=>m.bookId===book.id));$('#members-list').innerHTML=all.map(m=>{const u=state.db.users.find(u=>u.id===m.userId)||{name:'Pengguna',username:'—'};return `<div class="member-row"><div class="avatar">${initials(u.name)}</div><div class="member-info"><strong>${escapeHTML(u.name)} ${m.userId===state.user.id?'<small>(Anda)</small>':''}</strong><small>@${escapeHTML(u.username)}</small></div><select class="role-select" data-member-role="${m.userId}" ${currentRole()!=='owner'||m.role==='owner'?'disabled':''}><option value="owner" ${m.role==='owner'?'selected':''}>Pemilik</option><option value="editor" ${m.role==='editor'?'selected':''}>Editor</option><option value="viewer" ${m.role==='viewer'?'selected':''}>Pembaca</option></select></div>`;}).join('');$$('[data-member-role]').forEach(s=>s.addEventListener('change',async()=>{try{await api('shareBook',{bookId:state.activeBookId,username:state.db.users.find(u=>u.id===s.dataset.memberRole).username,role:s.value});toast('Peran anggota diperbarui.','success');}catch(e){toast(e.message,'error');renderMembers();}}));$('#invite-member').disabled=currentRole()!=='owner';}
function exportJournal(){const headers=['Tanggal','Referensi','Deskripsi','Kode akun','Akun','Debit','Kredit'];const rows=[];journals().slice().reverse().forEach(j=>linesFor(j.id).forEach(l=>{const a=accountById(l.accountId);rows.push([j.date,j.reference,j.description,a?.code||'',a?.name||'',l.debit,l.credit]);}));const csv=[headers,...rows].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const blob=new Blob(["\uFEFF"+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`jurnal-${activeBook().name.replace(/[^a-z0-9]+/ig,'-').toLowerCase()}.csv`;a.click();URL.revokeObjectURL(a.href);}

